import 'package:flutter_svg/flutter_svg.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:material_ui/material_ui.dart';
import 'package:tenpai/shared/models/tile.dart';
import 'package:tenpai/shared/theme/app_theme.dart';
import 'package:tenpai/shared/widgets/tile_state.dart';
import 'package:tenpai/shared/widgets/tile_widget.dart';

const _tile = Tile(suit: TileSuit.pin, number: 5, isRed: true);

// Regular is 64x88; this frame leaves 48 logical px on every side, enough
// for the badge overhang and the highlight halo to stay inside the capture.
Widget _frame({
  required TileState state,
  required ThemeMode mode,
  required Key boundaryKey,
}) => MaterialApp(
  theme: lightTheme(),
  darkTheme: darkTheme(),
  themeMode: mode,
  home: Scaffold(
    body: Center(
      child: RepaintBoundary(
        key: boundaryKey,
        child: SizedBox(
          width: 160,
          height: 184,
          child: Center(
            child: TileWidget(tile: _tile, state: state),
          ),
        ),
      ),
    ),
  ),
);

void main() {
  for (final state in TileState.values) {
    testWidgets('${state.name} tile matches its light golden', (tester) async {
      final boundaryKey = GlobalKey();
      await tester.pumpWidget(
        _frame(state: state, mode: .light, boundaryKey: boundaryKey),
      );
      // The tile symbol is an SvgPicture.asset: it decodes off-frame via a
      // real asset-bundle read, so pumpAndSettle alone leaves it blank.
      // vg.waitForPendingDecodes (vector_graphics-1.2.3 lib/src/vector_graphics.dart:656)
      // must run under runAsync to let that real I/O complete.
      await tester.runAsync(() => vg.waitForPendingDecodes());
      await tester.pumpAndSettle();

      await expectLater(
        find.byKey(boundaryKey),
        matchesGoldenFile('goldens/tile_regular_${state.name}_light.png'),
      );
    });

    testWidgets('${state.name} tile matches its dark golden', (tester) async {
      final boundaryKey = GlobalKey();
      await tester.pumpWidget(
        _frame(state: state, mode: .dark, boundaryKey: boundaryKey),
      );
      await tester.runAsync(() => vg.waitForPendingDecodes());
      await tester.pumpAndSettle();

      await expectLater(
        find.byKey(boundaryKey),
        matchesGoldenFile('goldens/tile_regular_${state.name}_dark.png'),
      );
    });
  }
}
